mapper.select:
SELECT *
FROM favorites
WHERE user_id = #{userId} 
AND job_id = #{jobId}
AND is_delete = 0

mapper.update:
UPDATE favorites
SET is_delete = 1
WHERE user_id = #{userId} AND job_id = #{jobId}

mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM favorites
    WHERE user_id = #{userId} 
    AND job_id = #{jobId}
    AND is_delete = 0
)
